<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x89C6;&#x9891;&#x8F6CGIF</text><text class="nav-icon"> </text></view></view><view class="content"><view class="pick-btn" @click="pickVideo"><text>{{ videoName || '&#x9009;&#x62E9;&#x89C6;&#x9891;' }}</text></view><view v-if="videoName" class="settings"><view class="setting-row"><text class="set-label">&#x5F00;&#x59CB;</text><input class="set-input" type="number" v-model.number="startTime" />s</view><view class="setting-row"><text class="set-label">&#x7ED3;&#x675F;</text><input class="set-input" type="number" v-model.number="endTime" />s</view><view class="setting-row"><text class="set-label">FPS</text><view class="fps-btns"><view class="fps-btn" :class="{active: fps===10}" @click="fps=10">10</view><view class="fps-btn" :class="{active: fps===15}" @click="fps=15">15</view><view class="fps-btn" :class="{active: fps===24}" @click="fps=24">24</view></view></view><view class="setting-row"><text class="set-label">&#x5C3A;&#x5BF8;</text><view class="size-btns"><view class="size-btn" :class="{active: size==='small'}" @click="size='small'">S</view><view class="size-btn" :class="{active: size==='medium'}" @click="size='medium'">M</view><view class="size-btn" :class="{active: size==='large'}" @click="size='large'">L</view></view></view></view><view class="convert-btn" @click="startConvert" :class="{disabled: !videoName}"><text>{{ converting ? convertingText : '&#x5F00;&#x59CB;&#x8F6C;&#x6362;' }}</text></view><view v-if="convertDone" class="result-box"><text class="result-text">&#x2705; &#x8F6C;&#x6362;&#x5B8C;&#x6210;</text><view class="save-btn" @click="saveGIF"><text>&#x4FDD;&#x5B58;GIF</text></view></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const videoName = ref("")
const startTime = ref(0)
const endTime = ref(5)
const fps = ref(15)
const size = ref("medium")
const converting = ref(false)
const convertDone = ref(false)
const convertingText = ref("")
function goBack() { uni.navigateBack() }
function pickVideo() { uni.chooseMedia({ count: 1, mediaType: ["video"], success: function(res) { videoName.value = "video_" + Date.now() + ".mp4"; convertDone.value = false } }) }
function startConvert() { if (!videoName.value) return; converting.value = true; convertDone.value = false; var steps = ["&#x5206;&#x6790;&#x89C6;&#x9891;...", "\u63D0\u53D6\u5E27...", "\u751F\u6210GIF...", "\u5B8C\u6210"]; var i = 0; convertingText.value = steps[0]; var timer = setInterval(function() { i++; if (i >= steps.length) { clearInterval(timer); converting.value = false; convertDone.value = true } else { convertingText.value = steps[i] } }, 1000) }
function saveGIF() { uni.showToast({ title: "GIF\u5DF2\u4FDD\u5B58", icon: "success" }) }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#f59e0b,#d97706);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.pick-btn{background:#fff;border-radius:16rpx;padding:40rpx;text-align:center;margin-bottom:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04);border:2rpx dashed #f59e0b}.pick-btn text{font-size:30rpx;color:#f59e0b}.settings{background:#fff;border-radius:16rpx;padding:24rpx;margin-bottom:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.setting-row{display:flex;align-items:center;margin-bottom:16rpx}.set-label{font-size:26rpx;color:#666;width:100rpx}.set-input{width:120rpx;height:64rpx;background:#f5f7fb;border-radius:8rpx;padding:0 12rpx;font-size:26rpx;border:2rpx solid #eee;margin:0 8rpx}.fps-btns,.size-btns{display:flex;gap:8rpx}.fps-btn,.size-btn{padding:12rpx 24rpx;background:#f5f7fb;border-radius:8rpx;font-size:24rpx;color:#666}.fps-btn.active,.size-btn.active{background:linear-gradient(135deg,#f59e0b,#d97706);color:#fff}.convert-btn{background:linear-gradient(135deg,#f59e0b,#d97706);border-radius:16rpx;padding:24rpx;text-align:center}.convert-btn text{font-size:30rpx;color:#fff;font-weight:600}.convert-btn.disabled{opacity:.5}.result-box{background:#fff;border-radius:16rpx;padding:24rpx;text-align:center;margin-top:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.result-text{font-size:30rpx;color:#f59e0b;font-weight:600;display:block;margin-bottom:16rpx}.save-btn{background:linear-gradient(135deg,#f59e0b,#d97706);border-radius:16rpx;padding:20rpx}.save-btn text{color:#fff;font-size:28rpx;font-weight:600}</style>